// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, uint256 length, address tokenAddr) public {
        vm.assume(tokenAddr.code.length == 0);
        uint256 n = bound(length, 1, 10);
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(from, i, tokenAddr)))));
            vals[i] = i + 1;
        }

        RecordingToken rec = new RecordingToken();
        bool ok;
        try c.transfer(from, address(rec), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && rec.count() == n);
    }
}

contract RecordingToken {
    uint256 public count;

    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}
